              if (msg.from === "visitante" && !msg.readByAdmin) {
                if (selectedUserIdRef.current !== user.id) {
                  toast.info(`Mensaje de ${userLabel}`, {
                    description: msg.texto || "Mensaje recibido",
                    duration: 5e3
                  });
                  notificationSound.play("good", 0.6);
                }
              }
